window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-8545f052af9baa30"]={"versions": [{"id": "FIG-8545f052af9baa30", "releases": ["R21-11", "R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Komponenten- und Verteilungsdiagramm der AUTOSAR Adaptive Platform (AP) zur Darstellung der Software- und Kommunikationsarchitektur für Softwareaktualisierungen über Diagnose- und Backend-Schnittstellen. Das Diagramm verortet funktionale Einheiten und Applikationen innerhalb eines Fahrzeugkontexts (<code>Vehicle</code>) auf einem Steuergerät (<code>«device» Adaptive ECU</code>) mit Unterteilung in <code>AUTOSAR Adaptive Application Layer</code> und <code>AUTOSAR Adaptive Platform Services + Foundation</code> sowie die Interaktion mit externen Cloud- und Werkstattsystemen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Vehicle / «device» Adaptive ECU</strong>: Physischer Ausführungskontext für die Adaptive Platform und darauf laufende Anwendungen.\n</li><li><strong>AUTOSAR Adaptive Application Layer</strong>:\n<ul class=\"fig-list\"><li><code>App A</code>, <code>App B</code>, <code>App ...</code>: Standardmäßige Adaptive Applications im System.\n</li><li><code>UCM Client (Diagnostic Application / UCM Master)</code>: Anwendungsseitiger Client, der die Schnittstellen des Update and Configuration Management konsumiert und als Vermittler für Diagnose- oder Master-gesteuerte Update-Vorgänge dient.\n</li></ul>\n</li><li><strong>AUTOSAR Adaptive Platform Services + Foundation</strong>:\n<ul class=\"fig-list\"><li><code>«ServiceProvider... UCM</code>: Update and Configuration Management Functional Cluster, der die standardisierten Dienste für Paketmanagement und Installation bereitstellt.\n</li><li><code>Diagnostic Manager (DM)</code>: Plattformkomponente zur Verarbeitung fahrzeugexterner Diagnoseprotokolle, ausgestattet mit einem Port (<code>DoIP socket</code>).\n</li></ul>\n</li><li><strong>Externe Entitäten</strong>:\n<ul class=\"fig-list\"><li><code>Server</code>: Backend-Server zur Bereitstellung von Softwarepaketen oder Update-Aufträgen.\n</li><li><code>Cloud</code>: Netzwerk- und Vermittlungsinfrastruktur zwischen Backend und Fahrzeug.\n</li><li><code>Diagnostic Client</code>: Externes Diagnosewerkzeug/Tester zur Initiierung und Überwachung von Update-Prozeduren über Werkstatt- oder Band-Schnittstellen.\n</li></ul>\n</li><li><strong>Schnittstellen &amp; Ports</strong>:\n<ul class=\"fig-list\"><li>Port <code>DoIP socket</code> am <code>Diagnostic Manager (DM)</code> und korrespondierender Port an der Fahrzeugaußengrenze.\n</li><li>Assoziationen zwischen externen Testern/Cloud-Systemen und den fahrzeuginternen Endpunkten (<code>«optional»</code>).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Diagnosebasierter Pfad</strong>: Der externe <code>Diagnostic Client</code> verbindet sich über eine optionale physikalische Verbindung mit dem Fahrzeug-Port und kommuniziert über DoIP mit dem <code>Diagnostic Manager (DM)</code>. Der <code>Diagnostic Manager (DM)</code> tauscht Steuerdaten mit dem <code>UCM Client (Diagnostic Application / UCM Master)</code> aus.\n</li><li><strong>Backend-/Cloud-Pfad</strong>: Der externe <code>Server</code> interagiert über die <code>Cloud</code> via optionaler Funk-/Netzwerkverbindung direkt bidirektional mit dem <code>UCM Client (Diagnostic Application / UCM Master)</code>.\n</li><li><strong>Lokale UCM-Ausführung</strong>: Der <code>UCM Client</code> steuert über die ara::com-Serviceschnittstelle unidirektional die Plattformkomponente <code>«ServiceProvider... UCM</code> an, um Paketdownload, Validierung und Aktivierung auf der Adaptive Platform durchzuführen.\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>UCM exponiert selbst keine proprietären Diagnose- oder Netzwerkprotokolle, sondern ausschließlich eine generische Service-Schnittstelle.\n</li><li>Die Abstraktion des Update-Transports (OTA via Backend oder physikalische Diagnose via DoIP) erfolgt vollständig in der Applikationsschicht über den <code>UCM Client</code>.\n</li><li>Für Entwickler definiert das Diagramm die Bindeglieder zwischen Diagnose-Stack (<code>Diagnostic Manager</code>), Backend-Anbindung und dem zentralen <code>UCM</code>-Dienstcluster für konforme Update-Mechanismen.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-d822deac482f55e5", "releases": ["R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Komponenten- und Verteilungsdiagramm der AUTOSAR Adaptive Platform (AP) zur Darstellung der Software- und Kommunikationsarchitektur für Softwareaktualisierungen über Diagnose- und Backend-Schnittstellen. Das Diagramm verortet funktionale Einheiten und Applikationen innerhalb eines Fahrzeugkontexts (<code>Vehicle</code>) auf einem Steuergerät (<code>«device» Adaptive ECU</code>) mit Unterteilung in <code>AUTOSAR Adaptive Application Layer</code> und <code>AUTOSAR Adaptive Platform Services + Foundation</code> sowie die Interaktion mit externen Cloud- und Werkstattsystemen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Vehicle / «device» Adaptive ECU</strong>: Ausführungskontext für die Adaptive Platform und Applikationen.\n</li><li><strong>AUTOSAR Adaptive Application Layer</strong>:\n<ul class=\"fig-list\"><li><code>App A</code>, <code>App B</code>: Adaptive Applications im System.\n</li><li><code>OTA Client</code>: Spezifische Anwendungskomponente zur Abwicklung von Over-The-Air-Update-Kampagnen (mit roter Markierung versehen).\n</li><li><code>UCM Client (Diagnostic Application)</code>: Spezifische Client-Applikation zur Verarbeitung und Umsetzung fahrzeuginterner Diagnoseanfragen für UCM.\n</li></ul>\n</li><li><strong>AUTOSAR Adaptive Platform Services + Foundation</strong>:\n<ul class=\"fig-list\"><li><code>«ServiceProvider... UCM</code>: Functional Cluster zur Durchführung von Update- und Konfigurationsprozessen auf der lokalen ECU.\n</li><li><code>V-UCM</code>: Plattforminstanz für fahrzeugweite Update-Koordination (Vehicle Update and Configuration Management).\n</li><li><code>Diagnostic Manager (DM)</code>: Plattformdienst mit <code>DoIP socket</code> für die Annahme externer Diagnosekommunikation.\n</li></ul>\n</li><li><strong>Externe Entitäten</strong>:\n<ul class=\"fig-list\"><li><code>Server «Image»</code>: Backend-Server für Software- und Kampagnenbereitstellung.\n</li><li><code>Cloud «Image»</code>: Drahtlose Infrastrukturverbindung.\n</li><li><code>Diagnostic Client «Image»</code>: Externer Diagnosetester.\n</li></ul>\n</li><li><strong>Schnittstellen &amp; Ports</strong>:\n<ul class=\"fig-list\"><li><code>DoIP socket</code> am <code>Diagnostic Manager (DM)</code> sowie Fahrzeugaußenanschluss (<code>«optional»</code>).\n</li><li>Drahtlose Schnittstelle (<code>«optional»</code>) zwischen <code>Cloud</code> und <code>OTA Client</code>.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Diagnosebasierter Pfad</strong>: Der externe <code>Diagnostic Client</code> verbindet sich über DoIP mit dem <code>Diagnostic Manager (DM)</code>. Der <code>Diagnostic Manager (DM)</code> leitet Diagnoseanforderungen unidirektional an den <code>UCM Client (Diagnostic Application)</code> weiter, welcher wiederum über die lokale UCM-Schnittstelle Aktionen bei <code>«ServiceProvider... UCM</code> anstößt.\n</li><li><strong>OTA-Kampagnenpfad</strong>: Der <code>Server</code> kommuniziert über die <code>Cloud</code> mit dem applikativen <code>OTA Client</code>. Der <code>OTA Client</code> übergibt die Update-Informationen an die Plattformkomponente <code>V-UCM</code>.\n</li><li><strong>Fahrzeugweite Koordination zu UCM</strong>: <code>V-UCM</code> steuert die lokale Plattformkomponente <code>«ServiceProvider... UCM</code> zur Durchführung der Softwareaktualisierungen an.\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Trennung der Zuständigkeiten im Applikationslayer zwischen rein diagnosebasiertem Update (<code>UCM Client (Diagnostic Application)</code>) und drahtlosem Flottenupdate (<code>OTA Client</code>).\n</li><li>Einführung von <code>V-UCM</code> als standardisiertem Plattformdienst für koordinierte Fahrzeug-Updates über den <code>OTA Client</code>.\n</li><li>Entwickler müssen Schnittstellen für OTA-Kampagnen an <code>V-UCM</code> anbinden, während lokale Diagnose-Updates weiterhin über den <code>Diagnostic Manager</code> und den diagnosebasierten UCM Client auf die UCM-Dienste zugreifen.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-1847c7995bb3ac6f", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Komponenten- und Verteilungsdiagramm der AUTOSAR Adaptive Platform (AP) zur Darstellung der Software- und Kommunikationsarchitektur für Softwareaktualisierungen über Diagnose- und Backend-Schnittstellen. Das Diagramm verortet funktionale Einheiten und Applikationen innerhalb eines Fahrzeugkontexts (<code>Vehicle</code>) auf einem Steuergerät (<code>«device» Adaptive ECU</code>) mit Unterteilung in <code>AUTOSAR Adaptive Application Layer</code> und <code>AUTOSAR Adaptive Platform Services + Foundation</code> sowie die Interaktion mit externen Cloud- und Werkstattsystemen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Vehicle / «device» Adaptive ECU</strong>: Ausführungskontext für die Adaptive Platform und Applikationen.\n</li><li><strong>AUTOSAR Adaptive Application Layer</strong>:\n<ul class=\"fig-list\"><li><code>App A</code>, <code>App B</code>: Adaptive Applications im System.\n</li><li><code>OTA Client</code>: Spezifische Anwendungskomponente zur Abwicklung von Over-The-Air-Update-Kampagnen.\n</li><li><code>UCM Client (Diagnostic Application)</code>: Client-Applikation zur Verarbeitung und Umsetzung fahrzeuginterner Diagnoseanfragen für UCM.\n</li></ul>\n</li><li><strong>AUTOSAR Adaptive Platform Services + Foundation</strong>:\n<ul class=\"fig-list\"><li><code>«ServiceProvider... UCM</code>: Functional Cluster zur Durchführung von Update- und Konfigurationsprozessen auf der lokalen ECU.\n</li><li><code>V-UCM</code>: Plattforminstanz für fahrzeugweite Update-Koordination (Vehicle Update and Configuration Management).\n</li><li><code>Diagnostic Manager (DM)</code>: Plattformdienst mit <code>DoIP socket</code> für die Annahme externer Diagnosekommunikation.\n</li></ul>\n</li><li><strong>Externe Entitäten</strong>:\n<ul class=\"fig-list\"><li><code>Server</code>: Backend-Server für Software- und Kampagnenbereitstellung.\n</li><li><code>Cloud</code>: Drahtlose Infrastrukturverbindung.\n</li><li><code>Diagnostic Client</code>: Externer Diagnosetester.\n</li></ul>\n</li><li><strong>Schnittstellen &amp; Ports</strong>:\n<ul class=\"fig-list\"><li><code>DoIP socket</code> am <code>Diagnostic Manager (DM)</code> sowie Fahrzeugaußenanschluss (<code>«optional»</code>).\n</li><li>Drahtlose Schnittstelle (<code>«optional»</code>) zwischen <code>Cloud</code> und <code>OTA Client</code>.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Diagnosebasierter Pfad</strong>: Der externe <code>Diagnostic Client</code> verbindet sich über DoIP mit dem <code>Diagnostic Manager (DM)</code>. Der <code>Diagnostic Manager (DM)</code> leitet Diagnoseanforderungen unidirektional an den <code>UCM Client (Diagnostic Application)</code> weiter, welcher wiederum über die lokale UCM-Schnittstelle Aktionen bei <code>«ServiceProvider... UCM</code> anstößt.\n</li><li><strong>OTA-Kampagnenpfad</strong>: Der <code>Server</code> kommuniziert über die <code>Cloud</code> mit dem applikativen <code>OTA Client</code>. Der <code>OTA Client</code> übergibt die Update-Informationen an die Plattformkomponente <code>V-UCM</code>.\n</li><li><strong>Fahrzeugweite Koordination zu UCM</strong>: <code>V-UCM</code> steuert die lokale Plattformkomponente <code>«ServiceProvider... UCM</code> zur Durchführung der Softwareaktualisierungen an.\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Trennung der Zuständigkeiten im Applikationslayer zwischen rein diagnosebasiertem Update (<code>UCM Client (Diagnostic Application)</code>) und drahtlosem Flottenupdate (<code>OTA Client</code>).\n</li><li>Einführung von <code>V-UCM</code> als standardisiertem Plattformdienst für koordinierte Fahrzeug-Updates über den <code>OTA Client</code>.\n</li><li>Entwickler müssen Schnittstellen für OTA-Kampagnen an <code>V-UCM</code> anbinden, während lokale Diagnose-Updates weiterhin über den <code>Diagnostic Manager</code> und den diagnosebasierten UCM Client auf die UCM-Dienste zugreifen.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-f727c27c0b228756", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Komponenten- und Verteilungsdiagramm der AUTOSAR Adaptive Platform (AP) zur Darstellung der Software- und Kommunikationsarchitektur für Softwareaktualisierungen über Diagnose- und Backend-Schnittstellen. Das Diagramm verortet funktionale Einheiten und Applikationen innerhalb eines Fahrzeugkontexts (<code>Vehicle</code>) auf einem Steuergerät (<code>«device» Adaptive ECU</code>) mit Unterteilung in <code>AUTOSAR Adaptive Application Layer</code> und <code>AUTOSAR Adaptive Platform Services + Foundation</code> sowie die Interaktion mit externen Cloud- und Werkstattsystemen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Vehicle / «device» Adaptive ECU</strong>: Ausführungskontext für die Adaptive Platform und Applikationen.\n</li><li><strong>AUTOSAR Adaptive Application Layer</strong>:\n<ul class=\"fig-list\"><li><code>App A</code>, <code>App B</code>: Adaptive Applications im System.\n</li><li><code>OTA Client</code>: Spezifische Anwendungskomponente zur Abwicklung von Over-The-Air-Update-Kampagnen.\n</li><li><code>UCM Client (Diagnostic Application)</code>: Client-Applikation zur Verarbeitung und Umsetzung fahrzeuginterner Diagnoseanfragen für UCM.\n</li></ul>\n</li><li><strong>AUTOSAR Adaptive Platform Services + Foundation</strong>:\n<ul class=\"fig-list\"><li><code>«ServiceProvider... UCM</code>: Functional Cluster zur Durchführung von Update- und Konfigurationsprozessen auf der lokalen ECU.\n</li><li><code>V-UCM</code>: Plattforminstanz für fahrzeugweite Update-Koordination (Vehicle Update and Configuration Management).\n</li><li><code>Diagnostic Manager (DM)</code>: Plattformdienst mit <code>DoIP socket</code> für die Annahme externer Diagnosekommunikation.\n</li></ul>\n</li><li><strong>Externe Entitäten</strong>:\n<ul class=\"fig-list\"><li><code>Server</code>: Backend-Server für Software- und Kampagnenbereitstellung.\n</li><li><code>Cloud</code>: Drahtlose Infrastrukturverbindung.\n</li><li><code>Diagnostic Client</code>: Externer Diagnosetester.\n</li></ul>\n</li><li><strong>Schnittstellen &amp; Ports</strong>:\n<ul class=\"fig-list\"><li><code>DoIP socket</code> am <code>Diagnostic Manager (DM)</code> sowie Fahrzeugaußenanschluss (<code>«optional»</code>).\n</li><li>Drahtlose Schnittstelle (<code>«optional»</code>) zwischen <code>Cloud</code> und <code>OTA Client</code>.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Diagnosebasierter Pfad</strong>: Der externe <code>Diagnostic Client</code> verbindet sich über DoIP mit dem <code>Diagnostic Manager (DM)</code>. Der <code>Diagnostic Manager (DM)</code> leitet Diagnoseanforderungen unidirektional an den <code>UCM Client (Diagnostic Application)</code> weiter, welcher wiederum über die lokale UCM-Schnittstelle Aktionen bei <code>«ServiceProvider... UCM</code> anstößt.\n</li><li><strong>OTA-Kampagnenpfad</strong>: Der <code>Server</code> kommuniziert über die <code>Cloud</code> mit dem applikativen <code>OTA Client</code>. Der <code>OTA Client</code> übergibt die Update-Informationen an die Plattformkomponente <code>V-UCM</code>.\n</li><li><strong>Fahrzeugweite Koordination zu UCM</strong>: <code>V-UCM</code> steuert die lokale Plattformkomponente <code>«ServiceProvider... UCM</code> zur Durchführung der Softwareaktualisierungen an.\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Trennung der Zuständigkeiten im Applikationslayer zwischen rein diagnosebasiertem Update (<code>UCM Client (Diagnostic Application)</code>) und drahtlosem Flottenupdate (<code>OTA Client</code>).\n</li><li>Einführung von <code>V-UCM</code> als standardisiertem Plattformdienst für koordinierte Fahrzeug-Updates über den <code>OTA Client</code>.\n</li><li>Entwickler müssen Schnittstellen für OTA-Kampagnen an <code>V-UCM</code> anbinden, während lokale Diagnose-Updates weiterhin über den <code>Diagnostic Manager</code> und den diagnosebasierten UCM Client auf die UCM-Dienste zugreifen.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-8545f052af9baa30", "to": "FIG-d822deac482f55e5", "fr": "R22-11", "tr": "R23-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Ersetzung der generischen Komponente <code>App ...</code> im <code>AUTOSAR Adaptive Application Layer</code> durch die spezifische Komponente <code>OTA Client</code> (versehen mit roter Markierung/Flag).\n</li><li>Änderung der Komponentenbezeichnung von <code>UCM Client (Diagnostic Application / UCM Master)</code> zu <code>UCM Client (Diagnostic Application)</code>.\n</li><li>Aufnahme der Plattformkomponente <code>V-UCM</code> (Vehicle UCM) in <code>AUTOSAR Adaptive Platform Services + Foundation</code>.\n</li><li>Umleitung des Cloud-Verbindungszweigs: Die bidirektionale Verbindung («optional») aus der <code>Cloud</code> führt nicht mehr zum <code>UCM Client</code>, sondern zum <code>OTA Client</code>.\n</li><li>Hinzufügung eines neuen Steuerungs-/Datenflusses vom <code>OTA Client</code> zur neuen Komponente <code>V-UCM</code>.\n</li><li>Hinzufügung einer Weiterleitung von <code>V-UCM</code> an <code>UCM</code> (<code>«ServiceProvider... UCM</code>).\n</li><li>Umstellung der Interaktion zwischen <code>Diagnostic Manager (DM)</code> und <code>UCM Client</code>: Invertierung der Pfeilrichtung zu einem Aufruf/Datenfluss vom DM zum UCM Client, anstelle der vorherigen Rückmeldung.\n</li><li>Hinzufügung eines Artefakt-Stereotyps <code>«Image»</code> an den externen Symbolen <code>Server</code>, <code>Cloud</code> und <code>Diagnostic Client</code>.\n</li></ul>"}, {"from": "FIG-d822deac482f55e5", "to": "FIG-1847c7995bb3ac6f", "fr": "R23-11", "tr": "R24-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Entfernung des Stereotyps <code>«Image»</code> unter den Bezeichnungen <code>Server</code>, <code>Cloud</code> und <code>Diagnostic Client</code>.\n</li><li>Korrektur des überlappenden Textlayouts bei <code>Diagnostic Client</code> (zuvor fehlerhaft als <code>«Imagient»</code> überdruckt).\n</li></ul>"}, {"from": "FIG-1847c7995bb3ac6f", "to": "FIG-f727c27c0b228756", "fr": "R24-11", "tr": "R25-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
